// @ts-check
const {themes: prismThemes} = require('prism-react-renderer');

/**
 * Assign a unique hierarchical translation key to every autogenerated sidebar category
 * so duplicate folder names (e.g. System, Obsolate, Tips) do not conflict during i18n builds.
 * @param {any[]} items
 * @param {string} prefix
 * @returns {any[]}
 */
function assignUniqueSidebarKeys(items, prefix = '') {
  return items.map((item) => {
    if (item.type === 'category') {
      const key = prefix ? `${prefix}/${item.label}` : item.label;
      return {
        ...item,
        key,
        items: assignUniqueSidebarKeys(item.items, key),
      };
    }
    return item;
  });
}

